# Letflow.Repo.Migrations.CreateNotificationFiles
#
# T-2596 (pilot gap G12) -- the tenant-scoped NOTIFICATION FILE AREA: the place
# the "file" channel of a notification step writes into.
#
# WHY A TABLE OF ITS OWN: the pilot's spike (section 2.h) found that no
# tenant-scoped area for generated files exists -- the attachment service keeps
# PHOTOS only (it runs an image check and a virus scan on every upload) and the
# data export streams a download without storing anything. A notification file
# is neither: the platform renders it, so the bytes never come from a tenant's
# upload.
#
# WHY NO FILE-SYSTEM PATH: the row holds the BYTES. A file that lives in a
# database cannot escape a directory, so "the file channel never writes to an
# arbitrary server path" holds by construction, not by a check that could be
# forgotten. The name of the row is generated by the SERVER (a sanitised stem
# plus a fresh uuid), so even a name that slipped past the activation fence
# cannot become a path.
#
# PLACEMENT: PER-TENANT (schema-per-tenant via `prefix()`), with `tenant_id uuid NOT NULL` in the
# row as well. The table starts empty: no existing row is altered.
#
# TENANT-SCOPED MIGRATION -- the `if prefix() do` guard is MANDATORY, and this file is
# registered in Letflow.TenantProvisioning's manifest (both halves are required). The only
# interpolated value is the trusted `prefix()` schema name, quoted as an identifier (INV-7).
defmodule Letflow.Repo.Migrations.CreateNotificationFiles do
  use Ecto.Migration

  def up do
    if prefix() do
      schema = prefix()

      execute("""
      CREATE TABLE "#{schema}".notification_files (
        id uuid PRIMARY KEY,
        tenant_id uuid NOT NULL,
        name text NOT NULL,
        template_key text NOT NULL,
        content_type text NOT NULL,
        byte_size integer NOT NULL
          CONSTRAINT notification_files_byte_size_chk CHECK (byte_size >= 0),
        sha256 text NOT NULL,
        bytes bytea NOT NULL,
        trigger_ref uuid,
        inserted_at timestamptz NOT NULL,
        expires_at timestamptz
      )
      """)

      execute(
        ~s|CREATE INDEX notification_files_inserted_at_index ON "#{schema}".notification_files (inserted_at DESC, id DESC)|
      )

      execute(
        ~s|CREATE INDEX notification_files_expires_at_index ON "#{schema}".notification_files (expires_at)|
      )
    end
  end

  def down do
    if prefix() do
      execute(~s|DROP TABLE IF EXISTS "#{prefix()}"."notification_files"|)
    end
  end
end
